def _harvest_candidate_ids(block_id: str) -> List[str]:
    """Exact id plus the Store ``_v2`` / kit-shelf alias (formula_executor)."""
    bid = str(block_id or "").strip()
    if not bid:
        return []
    ids = [bid]
    if bid.endswith("_v2") and len(bid) > 3:
        ids.append(bid[:-3])
    else:
        ids.append(f"{bid}_v2")
    seen: Dict[str, None] = {}
